#!/usr/bin/env bash

set -e

# Build Walert's searchable FAISS index from the passage vectors (generated by encode.sh)
# passage vectors -> FAISS HNSW index -> target/repro/indexes/
# c:

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT_DIR="$(cd "${SCRIPT_DIR}/../.." && pwd)"

ENCODER="tct_colbert-v2-hnp-msmarco"

EMBEDDINGS="${ROOT_DIR}/target/repro/embeddings/${ENCODER}"

INDEX="${ROOT_DIR}/target/repro/indexes/${ENCODER}-faiss"

# Do not mix files from an earlier index build with this one.
rm -rf "${INDEX}"
mkdir -p "$(dirname "${INDEX}")"

echo "Building Walert dense FAISS index"
echo "Embeddings: ${EMBEDDINGS}"
echo "Index:      ${INDEX}"

python -m pyserini.index.faiss \
  --input "${EMBEDDINGS}" \
  --output "${INDEX}" \
  --hnsw